package com.ke.ticketsystemke.service;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.WarrantyAttachmentRepository;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class WarrantyDocumentRequirementServiceTest{@Test void activationBoundaryPreservesHistoricalClaimsAndRequiresBillForNewClaims(){WarrantyAttachmentRepository repo=mock(WarrantyAttachmentRepository.class);when(repo.findByWarrantyClaim_IdOrderByUploadedAtDesc(any())).thenReturn(List.of());var service=new WarrantyDocumentRequirementService(repo,"2026-07-17T00:00:00Z");WarrantyClaim old=claim(Instant.parse("2026-07-16T00:00:00Z")),fresh=claim(Instant.parse("2026-07-18T00:00:00Z"));assertThat(service.summarize(old,null).requiredMissingCount()).isZero();assertThat(service.summarize(fresh,null).requiredMissingCount()).isEqualTo(1);fresh.setBillDocumentOverrideReason("Customer will provide later");var overridden=service.summarize(fresh,null).requirements().getFirst();assertThat(overridden.overridden()).isTrue();assertThat(overridden.present()).isFalse();assertThat(overridden.blocking()).isFalse();}private WarrantyClaim claim(Instant created){WarrantyClaim c=new WarrantyClaim();ReflectionTestUtils.setField(c,"id",1L);ReflectionTestUtils.setField(c,"createdAt",created);return c;}}
